import org.jsoup.safety.*;

public class HoleTest {
    public static void main(String[] args) {
        Safelist sl = Safelist.relaxed().addAttributes(":all", "style");
        String[] inputs = {
            "<div style=\"/* url(javascript:x) */color:red\">x</div>",
            "<div style=\"color/* url(javascript:x) */:red\">x</div>",
            "<div style=\"behavior /* */ : url(https://example.com/x.htc)\">x</div>",
            "<div style=\"-moz-binding /* */: url(https://example.com/b.xml)\">x</div>",
            "/*c*/<div style=\"/*c*/@import url(javascript:1);color:red\">x</div>",
        };
        for (String html : inputs) {
            Document d = Jsoup.parseBodyFragment(html, "https://example.com/a/b");
            String out = new Cleaner(sl).clean(d).body().html();
            System.out.println("IN : " + html.replace("/*c*/",""));
            System.out.println("OUT: " + out);
            System.out.println("LEAK: " + out.toLowerCase().contains("javascript") + "  binding/behavior leak: "
                + (out.contains("binding") || out.contains("behavior")));
            System.out.println();
        }
    }
}
