/**
 Tests whether the gap {@code [nameEnd, sepEnd)} just skipped is made up solely of block comments with no
 * whitespace and is followed immediately by another identifier character. A comment wedged between two
 * identifier runs ({@code ur/**\/l( ... )} or {@code expr/**\/ession( ... )}) does not join them under a strict
 * CSS tokenizer, but a lenient engine could read the glued run as a single token; such a declaration is rejected
 * rather than risk a split {@code url} or {@code expression} escaping recognition.
 */
private static boolean commentGluesNameToIdent(String value, int nameEnd, int sepEnd, int end) {
    if (sepEnd >= end || !isIdentChar(value.charAt(sepEnd))) return false;
    int i = nameEnd;
    boolean sawComment = false;
    while (i < sepEnd) {
        char c = value.charAt(i);
        if (isCssSpace(c)) return false; // real whitespace keeps the two runs distinct tokens
        if (c == '/' && i + 1 < sepEnd && value.charAt(i + 1) == '*') {
            int close = value.indexOf("*/", i + 2);
            if (close < 0 || close > sepEnd) return false;
            sawComment = true;
            i = close + 2;
            continue;
        }
        return false;
    }
    return sawComment;
}

