        Random r = new Random(42);
        Cleaner c = new Cleaner(sl);
        for (int n = 0; n < 20000; n++) {
            StringBuilder sb = new StringBuilder();
            int parts = 1 + r.nextInt(8);
            for (int i = 0; i < parts; i++) sb.append(toks[r.nextInt(toks.length)]);
