            Document d = Jsoup.parseBodyFragment(html, "https://example.com/a/b");
            Document o1 = c.clean(d);
            Document o2 = c.clean(o1); // idempotency
            if (!o1.body().html().equals(o2.body().html()))
                throw new AssertionError("not idempotent: " + style + "\n" + o1.body().html() + "\n" + o2.body().html());
            String ser = o1.toString();
            if (ser.toLowerCase().contains("javascript") || ser.toLowerCase().contains("vbscript")
                || ser.contains("-moz-binding") || ser.toLowerCase().contains("expression(") || ser.contains("behavior"))
